//@ProcessingGroup("thirdParty")
@Component("thirdParty-projector")
public class ThirdPartyProjector extends ThirdPartyEntityProjector {
		
	// core constructor
	public ThirdPartyProjector(ProjectorRegistry registry,
									ThirdPartyRepository repository,
									QueryUpdateEmitter queryUpdateEmitter ) {
        super(registry, repository);
        this.queryUpdateEmitter = queryUpdateEmitter;
    }	

	/*
     * @param	event CreateThirdPartyEvent
     */
    @EventHandler( payloadType=CreateThirdPartyEvent.class )
    public void handle( CreateThirdPartyEvent event) {
	    LOGGER.info("handling CreateThirdPartyEvent - " + event );
	    ThirdParty entity = new ThirdParty();
            entity.setThirdPartyId( event.getThirdPartyId() );
            entity.setName( event.getName() );
            entity.setTaxId( event.getTaxId() );
            entity.setAddress( event.getAddress() );
            entity.setPartyType( event.getPartyType() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllThirdParty( entity );
    }

    /*
     * @param	event UpdateThirdPartyEvent
     */
    @EventHandler( payloadType=UpdateThirdPartyEvent.class )
    public void handle( UpdateThirdPartyEvent event) {
    	LOGGER.info("handling UpdateThirdPartyEvent - " + event );
    	
	    ThirdParty entity = new ThirdParty();
            entity.setThirdPartyId( event.getThirdPartyId() );
            entity.setName( event.getName() );
            entity.setTaxId( event.getTaxId() );
            entity.setAddress( event.getAddress() );
            entity.setSubrogations( event.getSubrogations() );
            entity.setPartyType( event.getPartyType() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindThirdParty( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllThirdParty( entity );        
    }
    
    /*
     * @param	event DeleteThirdPartyEvent
     */
    @EventHandler( payloadType=DeleteThirdPartyEvent.class )
    public void handle( DeleteThirdPartyEvent event) {
    	LOGGER.info("handling DeleteThirdPartyEvent - " + event );
    	
    	// ------------------------------------------
    	// delete delegation
    	// ------------------------------------------
    	ThirdParty entity = delete( event.getThirdPartyId() );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllThirdParty( entity );

    }    


    /*
     * @param	event AssignSubrogationsToThirdPartyEvent
     */
    @EventHandler( payloadType=AssignSubrogationsToThirdPartyEvent.class)
    public void handle( AssignSubrogationsToThirdPartyEvent event) {
	    LOGGER.info("handling AssignSubrogationsToThirdPartyEvent - " + event );
	    
	    // ------------------------------------------
    	// delegate to addTo 
    	// ------------------------------------------ 
	    ThirdParty entity = addToSubrogations(event.getThirdPartyId(), event.getAddTo() );
        
    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindThirdParty( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllThirdParty( entity );
    }
    

/*
 * @param	event RemoveSubrogationsFromThirdPartyEvent
 */
@EventHandler( payloadType=RemoveSubrogationsFromThirdPartyEvent.class)
public void handle( RemoveSubrogationsFromThirdPartyEvent event) {
    LOGGER.info("handling RemoveSubrogationsFromThirdPartyEvent - " + event );

    ThirdParty entity = removeFromSubrogations(event.getThirdPartyId(), event.getRemoveFrom() );
    
	// ------------------------------------------
	// emit to subscribers that find one
	// ------------------------------------------    	
    emitFindThirdParty( entity );

	// ------------------------------------------
	// emit to subscribers that find all
	// ------------------------------------------    	
    emitFindAllThirdParty( entity );
}



    /**
     * Method to retrieve the ThirdParty via an ThirdPartyPrimaryKey.
     * @param 	id Long
     * @return 	ThirdParty
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public ThirdParty handle( FindThirdPartyQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getThirdPartyId() );
    }
    
    /**
     * Method to retrieve a collection of all ThirdPartys
     *
     * @param	query	FindAllThirdPartyQuery 
     * @return 	List<ThirdParty> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<ThirdParty> handle( FindAllThirdPartyQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindThirdParty,
 * but only if the id matches
 *
 * @param		entity	ThirdParty
 */
	protected void emitFindThirdParty( ThirdParty entity ) {
		LOGGER.info("handling emitFindThirdParty" );
		
	    queryUpdateEmitter.emit(FindThirdPartyQuery.class,
	                            query -> query.getFilter().getThirdPartyId().equals(entity.getThirdPartyId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllThirdParty
	 * 
	 * @param		entity	ThirdParty
	 */
	protected void emitFindAllThirdParty( ThirdParty entity ) {
		LOGGER.info("handling emitFindAllThirdParty" );
		
	    queryUpdateEmitter.emit(FindAllThirdPartyQuery.class,
	                            query -> true,
	                            entity);
	}

	//--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
	private final QueryUpdateEmitter queryUpdateEmitter;
    private static final Logger LOGGER 	= Logger.getLogger(ThirdPartyProjector.class.getName());

}
